import { Node, Edge, Group, Vertex } from "./model/graph";
/**
 * Offers methods to invoke operations on dataset contents, and to filter the contents.
 * @group Model
 */
export interface FilterableDataset {
    /**
     * Invoke the given function on each node in the dataset
     * @param fn
     */
    eachNode(fn: (i: number, n: Node) => void): void;
    /**
     * Invoke the given function on each edge in the dataset
     * @param fn
     */
    eachEdge(fn: (i: number, e: Edge) => void): void;
    /**
     * Invoke the given function on each group in the dataset
     * @param fn
     */
    eachGroup(fn: (i: number, e: Group) => void): void;
    /**
     * Invoke the given function on each vertex (node or group) in the dataset
     * @param fn
     */
    eachVertex(fn: (i: number, e: Vertex) => void): void;
    /**
     * Filter the dataset and return a filtered copy.
     * @param spec
     * @param includePartials
     */
    filter(spec: any, includePartials?: boolean): any;
}
/**
 * @internal
 * @param obj
 */
export declare function isFilterableDataset(obj: any): obj is FilterableDataset;
